const PATH_ROUTES = Object.fromEntries(Object.entries(ROUTE_PATHS).map(([route,path])=>[path,route]));
function normalizePathname(pathname){
  let path=String(pathname||"/").replace(/\/+/g,"/");
  if(!path.startsWith("/"))path="/"+path;
  path=path.replace(/\/index\.html$/,"/");
  if(path!=="/"&&!path.endsWith("/"))path+="/";
  return path;
}
function slugifyText(value){
  return String(value||"")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g,"")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,"-")
    .replace(/-+/g,"-")
    .replace(/^-|-$/g,"")
    .slice(0,86)
    .replace(/-$/g,"") || "news";
}
function newsSlug(n){
  const rawId = n && (n.id || n.sourceId || n.date) || "item";
  return `${slugifyText(n && n.title || "news")}-${slugifyText(rawId).slice(0,32)}`;
}
function newsPath(n){return `/news/${newsSlug(n)}/`;}
function routeFromPath(pathname){
  const path=normalizePathname(pathname);
  if(path.startsWith("/news/")&&path!=="/news/"){
    const parts=path.split("/").filter(Boolean);
    return `article-${decodeURIComponent(parts.slice(1).join("/"))}`;
  }
  return PATH_ROUTES[path] || "home";
}
function appPathForRoute(id){
  const target=String(id||"home");
  if(target.startsWith("article-")){
    const key=target.replace(/^article-/,"");
    const article=(state.news||[]).find(x=>String(x.id)===String(key)||newsSlug(x)===String(key)||newsSlug(x)===decodeURIComponent(String(key)));
    return article?newsPath(article):`/news/${encodeURIComponent(key)}/`;
  }
  return ROUTE_PATHS[target] || `/#${target}`;
}
const initialNewsParam = new URLSearchParams(location.search).get("news");
let current = location.hash.replace("#","") || (initialNewsParam ? `article-${initialNewsParam}` : routeFromPath(location.pathname));
let view = {staff:"prima", calendar:"prima", calendarFilter:"Tutte", calendarPage:1, standings:"prima", cup:"prima", stats:"prima", statsCompetition:"totale", squadPage:1, squadTeam:"Prima squadra", newsPage:1, newsCategory:"Tutte", galleryPage:1, galleryCategory:"Tutte", gallerySeason:"2025/26", videoPage:1, videoCategory:"Tutte", videoSeason:"2025/26", clubHistoryIndex:0};

function teamSwitch(kind){
  const currentValue = view[kind] || (kind==="staff" ? "tecnico" : "prima");
  if(kind==="staff"){
    return `<div class="team-switch"><button class="${currentValue==='tecnico'?'active':''}" onclick="setView('staff','tecnico')">Staff tecnico</button><button class="${currentValue==='dirigenza'?'active':''}" onclick="setView('staff','dirigenza')">Dirigenza</button></div>`;
  }
  return `<div class="team-switch"><button class="${currentValue==='prima'?'active':''}" onclick="setView('${kind}','prima')">Prima squadra</button><button class="${currentValue==='u21'?'active':''}" onclick="setView('${kind}','u21')">Under 21</button></div>`;
}
function setView(kind,value){
  view[kind]=value;
  if(kind==="calendar"){view.calendarPage=1;fixtures();return;}
  if(kind==="standings"){standings();return;}
  if(kind==="cup"){coppa();return;}
  if(kind==="stats"){stats();return;}
  if(kind==="staff"){staff();return;}
}

const $ = s => document.querySelector(s);
const app = $("#app");
function hydrate(src = {}) {
  // Il CMS deve essere la sorgente primaria.
  // Se una collection esiste in content/data.json, usiamo ESATTAMENTE quella.
  // Questo evita che elementi eliminati dal CMS vengano "resuscitati" dai defaults interni.
  const arrayKeys = [
    "news",
    "roster",
    "fixtures",
    "u21Fixtures",
    "standings",
    "u21Standings",
    "staff",
    "galleryAlbums",
    "sponsors",
    "videos",
    "social",
    "socialFeed",
    "sponsorPackages",
    "leads"
  ];

  const objectKeys = [
    "cup",
    "u21Cup",
    "historicalStats",
    "automation"
  ];

  const hydrated = { ...defaults, ...src };

  arrayKeys.forEach((key) => {
    hydrated[key] = Array.isArray(src[key]) ? src[key] : (defaults[key] || []);
  });

  objectKeys.forEach((key) => {
    hydrated[key] = src[key] && typeof src[key] === "object" ? src[key] : (defaults[key] || {});
  });

  return hydrated;
}

// ===== AUTOMAZIONI STAGIONE: incrementa i dati esistenti, non li azzera =====
function deepClone(obj){return JSON.parse(JSON.stringify(obj || {}));}
function toNumber(v){const x=Number(v);return Number.isFinite(x)?x:0;}
function currentSeasonOf(data){return (data.automation && data.automation.currentSeason) || "2026/2027";}
function normText(v){return String(v||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]/g,"");}
function normalizeCmsStatus(value){const t=normText(value);if(!t||t==="dagiocare"||t==="scheduled"||t==="toplay")return "Da giocare";if(t==="terminata"||t==="finita"||t==="finished"||t==="played")return "Terminata";return value||"Da giocare";}
function normalizeCmsCompetition(value){const t=normText(value);if(t==="coppa")return "Coppa";if(t==="playoff")return "Playoff";return value||"Campionato";}
function normalizeCmsMatch(match){if(!match||typeof match!=="object")return match;const out={...match};out.status=normalizeCmsStatus(out.status);if(out.competition!==undefined)out.competition=normalizeCmsCompetition(out.competition);if(out.lineup&&typeof out.lineup==="object"){out.lineup={...out.lineup};["startingFive","bench","suspended","injured"].forEach(k=>{out.lineup[k]=Array.isArray(out.lineup[k])?out.lineup[k].map(String).filter(Boolean):[];});}["scorerEvents","yellowCardEvents","redCardEvents","goalkeeperEvents"].forEach(k=>{if(Array.isArray(out[k]))out[k]=out[k].map(ev=>{const clean={...(ev||{})};if(clean.playerId!==undefined&&clean.playerId!==null)clean.playerId=String(clean.playerId);["goals","cards","goalsAgainst","minutes","appearances"].forEach(n=>{if(clean[n]!==undefined&&clean[n]!==null&&clean[n]!=="")clean[n]=Number(clean[n]);});return clean;});});return out;}
function unwrapPublishedData(payload){if(payload&&typeof payload.raw==="string"){try{return JSON.parse(payload.raw);}catch(e){console.warn("data.json contiene raw ma non è JSON valido",e);}}if(payload&&payload.path==="content/data.json"&&payload.data&&typeof payload.data==="object")return payload.data;return payload||{};}
function normalizePublishedData(payload){const out={...unwrapPublishedData(payload)};if(Array.isArray(out.fixtures))out.fixtures=out.fixtures.map(normalizeCmsMatch);if(Array.isArray(out.u21Fixtures))out.u21Fixtures=out.u21Fixtures.map(normalizeCmsMatch);if(out.cup&&typeof out.cup==="object"){out.cup={...out.cup};if(Array.isArray(out.cup.fixtures))out.cup.fixtures=out.cup.fixtures.map(normalizeCmsMatch);}if(out.u21Cup&&typeof out.u21Cup==="object"){out.u21Cup={...out.u21Cup};if(Array.isArray(out.u21Cup.fixtures))out.u21Cup.fixtures=out.u21Cup.fixtures.map(normalizeCmsMatch);}return out;}
function competitionKeyFromMatch(match, sourceType){const raw=normText((match&&(match.competition||match._calendarType))||sourceType||(match&&match.round)||"");return raw.includes("coppa")||raw==="cup"?"coppa":"campionato";}
function scoreParts(score){const parts=String(score||"").match(/\d+/g);if(!parts||parts.length<2)return null;return [parseInt(parts[0],10),parseInt(parts[1],10)];}
function isTerminatedMatch(m){return normText(m.status)==="terminata" && !!scoreParts(m.score);}
function isCusName(name){const t=normText(name);return t.includes("custrento")||t.includes("custrentocalcioa5")||t==="cus";}
function isU21Match(m, sourceType){return sourceType==="u21" || sourceType==="u21cup" || normText(m.home).includes("u21") || normText(m.away).includes("u21");}
function goalsForAgainst(m){const score=scoreParts(m.score);if(!score)return {forGoals:0,againstGoals:0};const homeCus=isCusName(m.home);const awayCus=isCusName(m.away);return {forGoals: homeCus?score[0]:(awayCus?score[1]:0), againstGoals: homeCus?score[1]:(awayCus?score[0]:0)};}
function isCusMatchForStats(m,isU21){
  const hasCus=isCusName(m.home)||isCusName(m.away);
  if(!hasCus)return false;
  const team=String(m._statsTeam||"").toLowerCase();
  if(team)return team===(isU21?"u21":"prima");
  const hasU21=normText(m.home).includes("u21")||normText(m.away).includes("u21");
  return isU21?hasU21:!hasU21;
}
function playerDisplayNameById(roster,id){const p=(roster||[]).find(x=>String(x.id)===String(id));return p?p.name:String(id||"");}
function resolvePlayerId(value, roster){
  if(value && typeof value==="object") value=value.playerId||value.id||value.g||value.name||value.player||value.value;
  if(value===0||value){
    const direct=(roster||[]).find(p=>String(p.id)===String(value));if(direct)return direct.id;
    const key=normText(value);
    const byName=(roster||[]).find(p=>normText(p.name)===key) || (roster||[]).find(p=>normText(p.name).includes(key)||key.includes(normText(p.name)));
    if(byName)return byName.id;
  }
  return null;
}
function lineupIds(match, roster){const l=match.lineup||{};const values=[...(l.startingFive||[]),...(l.bench||[])];const ids=[];values.forEach(v=>{const id=resolvePlayerId(v,roster);if(id!==null&&!ids.includes(id))ids.push(id);});return ids;}
function startingLineupIds(match, roster){const l=match.lineup||{};const ids=[];(l.startingFive||[]).forEach(v=>{const id=resolvePlayerId(v,roster);if(id!==null&&!ids.includes(id))ids.push(id);});return ids;}
function isGoalkeeperPlayer(p){return !!p && (p.role==="Portiere"||!!p.goalkeeperStats);}
function startingGoalkeeperId(match, roster){const l=match.lineup||{};for(const v of (l.startingFive||[])){const id=resolvePlayerId(v,roster);const p=(roster||[]).find(x=>String(x.id)===String(id));if(isGoalkeeperPlayer(p))return p.id;}return null;}
function scorerEvents(match, roster){
  const events=[];
  (match.scorerEvents||[]).forEach(e=>{const id=resolvePlayerId(e.playerId||e.player||e.name||e.id,e.playerId?roster:roster);const goals=Math.max(1,toNumber(e.goals||e.value||1));if(id!==null)events.push({playerId:id,goals});});
  if(events.length)return events;
  (match.scorers||[]).forEach(raw=>{const txt=String(raw||"");let goals=1;const m=txt.match(/(\d+)\s*$/);if(m)goals=parseInt(m[1],10);const cleaned=txt.replace(/\d+\s*$/," ").trim();const id=resolvePlayerId(cleaned,roster);if(id!==null)events.push({playerId:id,goals});});
  return events;
}
function scorerText(match){const events=scorerEvents(match,state.roster||[]);if(events.length){return events.map(e=>`${playerDisplayNameById(state.roster,e.playerId)}${e.goals>1?` ${e.goals}`:""}`).join(", ");}return (match.scorers||[]).join(", ")||"Da definire";}
function toList(v){return Array.isArray(v)?v:(v?[v]:[]);}
function statCount(v, fallback=1){const n=toNumber(v);return n>0?n:fallback;}
function statEventList(match, roster, objectKeys, legacyKeys, countKeys){
  const events=[];
  objectKeys.forEach(key=>{
    toList(match[key]).forEach(ev=>{
      const id=resolvePlayerId(ev&&typeof ev==="object"?(ev.playerId||ev.player||ev.name||ev.id):ev, roster);
      const count=statCount(countKeys.map(k=>ev&&typeof ev==="object"?ev[k]:null).find(v=>toNumber(v)>0),1);
      if(id!==null)events.push({playerId:id,count});
    });
  });
  legacyKeys.forEach(key=>{
    toList(match[key]).forEach(raw=>{
      const id=resolvePlayerId(raw, roster);
      if(id!==null)events.push({playerId:id,count:1});
    });
  });
  return events;
}
function yellowCardEvents(match, roster){return statEventList(match,roster,["yellowCardEvents","yellowEvents","yellowCards"],["yellow"],["cards","yellow","count","value"]);}
function redCardEvents(match, roster){return statEventList(match,roster,["redCardEvents","redEvents","redCards"],["red"],["cards","red","count","value"]);}
function cardText(match,type){
  const events=type==="red"?redCardEvents(match,state.roster||[]):yellowCardEvents(match,state.roster||[]);
  if(events.length)return events.map(e=>`${playerDisplayNameById(state.roster,e.playerId)}${e.count>1?` ${e.count}`:""}`).join(", ");
  return "Nessuno";
}
function goalkeeperAgainstEvents(match, roster, againstGoals){
  const raw=[...toList(match.goalkeeperEvents),...toList(match.goalkeeperGoalsAgainst),...toList(match.goalsAgainstEvents)];
  const events=[];
  raw.forEach(ev=>{
    const id=resolvePlayerId(ev&&typeof ev==="object"?(ev.playerId||ev.player||ev.name||ev.id):ev, roster);
    if(id===null)return;
    const goalsAgainst=statCount(ev&&typeof ev==="object"?(ev.goalsAgainst||ev.against||ev.goals||ev.value):againstGoals, againstGoals);
    const minutes=toNumber(ev&&typeof ev==="object"?ev.minutes:0)||40;
    const appearances=(ev&&typeof ev==="object"&&ev.appearances===0)?0:1;
    events.push({playerId:id,goalsAgainst,minutes,appearances});
  });
  if(events.length)return events;
  const gkId=startingGoalkeeperId(match,roster);
  return gkId!==null?[{playerId:gkId,goalsAgainst:againstGoals,minutes:40,appearances:1}]:[];
}
function playerCardsShape(p){
  const src=p.cards||p.cardStats||p.discipline||{};
  const empty={yellow:0,red:0};
  const out={campionato:{...empty,...(src.campionato||{})},coppa:{...empty,...(src.coppa||{})},totale:{...empty,...(src.totale||{})}};
  ["campionato","coppa","totale"].forEach(k=>{out[k].yellow=toNumber(out[k].yellow);out[k].red=toNumber(out[k].red);});
  return out;
}
function prettyDate(v){if(!v)return "—";const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);return new Intl.DateTimeFormat("it-IT",{day:"2-digit",month:"2-digit",year:"numeric"}).format(d);}
function playerBirthDate(p){return p.birthDate||p.dateOfBirth||p.dob||"";}
function playerBirthPlace(p){return p.birthPlace||p.placeOfBirth||p.birthplace||"";}
function playerFaculty(p){return p.faculty||p.universityFaculty||p.universityCourse||p.university||p.course||"";}
function compLabel(key){return key==="campionato"?"Campionato":(key==="coppa"?"Coppa":"Complessivo");}

function ensurePlayerStatShape(p){
  const out={...p};
  const camp=out.competitions&&out.competitions.campionato?{...out.competitions.campionato}:{appearances:0,goals:0,assists:0};
  const coppa=out.competitions&&out.competitions.coppa?{...out.competitions.coppa}:{appearances:0,goals:0,assists:0};
  const totale=out.competitions&&out.competitions.totale?{...out.competitions.totale}:{appearances:toNumber(out.appearances),goals:toNumber(out.goals),assists:toNumber(out.assists)};
  out.competitions={campionato:{appearances:toNumber(camp.appearances),goals:toNumber(camp.goals),assists:toNumber(camp.assists)},coppa:{appearances:toNumber(coppa.appearances),goals:toNumber(coppa.goals),assists:toNumber(coppa.assists)},totale:{appearances:toNumber(totale.appearances),goals:toNumber(totale.goals),assists:toNumber(totale.assists)}};
  out.cards=playerCardsShape(out);
  out.appearances=toNumber(out.appearances)||out.competitions.totale.appearances;
  out.goals=toNumber(out.goals)||out.competitions.totale.goals;
  out.assists=toNumber(out.assists)||out.competitions.totale.assists;
  if(out.role==="Portiere"||out.goalkeeperStats){
    const gs=out.goalkeeperStats?{...out.goalkeeperStats}:{};
    const by=gs.byCompetition?deepClone(gs.byCompetition):{};
    ["campionato","coppa","totale"].forEach(k=>{by[k]=by[k]||{appearances:0,minutes:0,cleanSheets:0,goalsAgainst:0};by[k].appearances=toNumber(by[k].appearances);by[k].minutes=toNumber(by[k].minutes);by[k].cleanSheets=toNumber(by[k].cleanSheets);by[k].goalsAgainst=toNumber(by[k].goalsAgainst);});
    gs.appearances=toNumber(gs.appearances);gs.minutes=toNumber(gs.minutes);gs.cleanSheets=toNumber(gs.cleanSheets);gs.goalsAgainst=toNumber(gs.goalsAgainst);gs.saves=toNumber(gs.saves);gs.penaltiesSaved=toNumber(gs.penaltiesSaved);gs.saveRate=toNumber(gs.saveRate);gs.goalsAgainstAvg=toNumber(gs.goalsAgainstAvg);gs.byCompetition=by;out.goalkeeperStats=gs;
  }
  return out;
}
function titleCaseWords(v){
  return String(v||"").toLowerCase().split(/\s+/).filter(Boolean).map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(" ");
}
function historicalPlayerName(name){
  const raw=String(name||"").trim().replace(/\s+/g," ");
  const key=normText(raw);
  const aliases={
    "lucacirasola":"Cirasola",
    "cesarevettorazzi":"Vettorazzi",
    "mattiavaia":"Vaia Mattia",
    "marcovaia":"Vaia Marco",
    "andreamartinelli":"Martinelli A.",
    "eliamartinelli":"Martinelli E.",
    "luccabaccarozeni":"Baccaro Zeni",
    "lucabaccarozeni":"Baccaro Zeni",
    "safisaifedine":"Safi",
    "saifedinesafi":"Safi",
    "luca frattolin":"Frattolin",
    "lucafrattolin":"Frattolin",
    "luca frattoln":"Frattolin",
    "lucafrattoln":"Frattolin",
    "filippobaietta":"Baietta",
    "filippobernard":"Bernard",
    "tommasoboldrini":"Boldrini",
    "davidefilippi":"Filippi",
    "alvisetesser":"Tesser",
    "federicoaddobbati":"Addobbati",
    "mattiacuman":"Cuman",
    "federicomaciocia":"Maciocia",
    "alessandrozanetti":"Zanetti",
    "damianoloperfido":"Loperfido",
    "diego conti":"Conti",
    "diegoconti":"Conti"
  };
  if(aliases[key])return aliases[key];
  const parts=raw.split(" ").filter(Boolean);
  if(parts.length<=1)return titleCaseWords(raw);
  const first=titleCaseWords(parts[0]);
  const last=titleCaseWords(parts[parts.length-1]);
  const lastKey=normText(last);
  if(lastKey==="vaia")return `Vaia ${first}`;
  if(lastKey==="martinelli")return `Martinelli ${first.charAt(0).toUpperCase()}.`;
  if(key.includes("baccarozeni"))return "Baccaro Zeni";
  if(key.includes("caccianeff"))return "Caccia Neff";
  if(raw===raw.toUpperCase())return titleCaseWords(parts[0]);
  return last;
}
function mergeTiedRankingMap(map){
  const groups=new Map();
  [...map.values()].forEach(item=>{
    const value=toNumber(item.value);
    if(!groups.has(value))groups.set(value,[]);
    groups.get(value).push(item);
  });
  return [...groups.entries()]
    .sort((a,b)=>toNumber(b[0])-toNumber(a[0]))
    .map(([value,items])=>({
      players:items.sort((a,b)=>a.order-b.order).map(x=>x.display).join(", "),
      value:toNumber(value)
    }));
}
function rankingToIndividualMap(rows){
  const map=new Map();
  let order=0;
  (rows||[]).forEach(r=>{
    const value=toNumber(r.value);
    String(r.players||"").split(",").map(x=>x.trim()).filter(Boolean).forEach(name=>{
      const display=titleCaseWords(name).replace(/\bA\.$/,"A.").replace(/\bE\.$/,"E.");
      const key=normText(display);
      if(!map.has(key))map.set(key,{key,display,value,order:order++});
    });
  });
  return map;
}
function bumpRanking(rows, name, amount){
  if(!amount)return rows||[];
  const map=rankingToIndividualMap(rows);
  const display=historicalPlayerName(name);
  const key=normText(display);
  if(map.has(key)){
    const item=map.get(key);
    item.value=toNumber(item.value)+toNumber(amount);
    item.display=display;
  }else{
    map.set(key,{key,display,value:toNumber(amount),order:map.size+10000});
  }
  return mergeTiedRankingMap(map);
}

function avgPerGame(total,played){
  const p=toNumber(played);
  return p?(toNumber(total)/p).toFixed(2).replace('.',','):"0";
}
function bestWinsSeason(hs){
  const seasons=(hs&&hs.seasons)||[];
  if(!seasons.length)return {label:"Stagione con più vittorie",value:"—",detail:"Dato non disponibile"};
  const best=seasons.reduce((acc,row)=>toNumber(row.wins)>toNumber(acc.wins)?row:acc,seasons[0]);
  return {label:"Stagione con più vittorie",value:best.season||"—",detail:`${toNumber(best.wins)} vittorie`};
}

function historicalWithCurrentSeason(hsRaw,current,season,playerIncrements){
  const hs=deepClone(hsRaw||{});if(!hs.summary)return hs;
  const cur={season,played:toNumber(current.played),wins:toNumber(current.wins),draws:toNumber(current.draws),losses:toNumber(current.losses),goalsFor:toNumber(current.goalsFor),goalsAgainst:toNumber(current.goalsAgainst)};
  cur.goalDifference=cur.goalsFor-cur.goalsAgainst;cur.goalsForAvg=cur.played?(cur.goalsFor/cur.played).toFixed(2).replace('.',','):"0";cur.goalsAgainstAvg=cur.played?(cur.goalsAgainst/cur.played).toFixed(2).replace('.',','):"0";
  hs.seasons=(hs.seasons||[]).filter(s=>String(s.season)!==String(season));if(cur.played>0)hs.seasons=[cur,...hs.seasons];
  const s=hs.summary;["played","wins","draws","losses","goalsFor","goalsAgainst"].forEach(k=>{s[k]=toNumber(s[k])+toNumber(cur[k]);});s.goalDifference=s.goalsFor-s.goalsAgainst;s.goalsForAvg=s.played?(s.goalsFor/s.played).toFixed(2).replace('.',','):"0";s.goalsAgainstAvg=s.played?(s.goalsAgainst/s.played).toFixed(2).replace('.',','):"0";
  (playerIncrements.goals||[]).forEach(x=>{hs.allTimeGoals=bumpRanking(hs.allTimeGoals,x.name,x.value);});
  (playerIncrements.appearances||[]).forEach(x=>{hs.allTimeAppearances=bumpRanking(hs.allTimeAppearances,x.name,x.value);});
  const bestWins=bestWinsSeason(hs);
  hs.highlights=[
    {label:"Gare ufficiali",value:s.played,detail:`Totale storico aggiornato con ${season}`},
    {label:"Vittorie",value:s.wins,detail:"Vittorie complessive storiche"},
    {label:"Gol fatti",value:s.goalsFor,detail:`Media ${avgPerGame(s.goalsFor,s.played)} gol a partita`},
    bestWins,
    {label:"Differenza reti",value:(s.goalDifference>0?`+${s.goalDifference}`:`${s.goalDifference}`),detail:"Saldo reti complessivo"}
  ];
  return hs;
}
function applyAutomations(baseData){
  if(baseData.automation && baseData.automation.enabled===false)return baseData;
  const season=currentSeasonOf(baseData);
  const out={...baseData,roster:(baseData.roster||[]).map(ensurePlayerStatShape)};
  const byId=new Map(out.roster.map(p=>[String(p.id),p]));
  const empty=()=>({played:0,wins:0,draws:0,losses:0,goalsFor:0,goalsAgainst:0});
  const teamStats={prima:{campionato:empty(),coppa:empty()},u21:{campionato:empty(),coppa:empty()}};
  const playerIncrements={goals:[],appearances:[]};
  const goalMap=new Map(), appMap=new Map();
  const addMap=(map,id,val)=>map.set(String(id),(map.get(String(id))||0)+val);

  function addCards(p,comp,yellow,red){
    p.cards=p.cards||playerCardsShape(p);
    p.cards[comp].yellow=toNumber(p.cards[comp].yellow)+toNumber(yellow);
    p.cards[comp].red=toNumber(p.cards[comp].red)+toNumber(red);
    p.cards.totale.yellow=toNumber(p.cards.totale.yellow)+toNumber(yellow);
    p.cards.totale.red=toNumber(p.cards.totale.red)+toNumber(red);
  }

  function processMatch(match,sourceType){
    if(!isTerminatedMatch(match))return;
    const comp=competitionKeyFromMatch(match,sourceType);
    const teamKey=isU21Match(match,sourceType)?"u21":"prima";
    const gfga=goalsForAgainst(match);
    const bucket=teamStats[teamKey][comp];
    bucket.played++;bucket.goalsFor+=gfga.forGoals;bucket.goalsAgainst+=gfga.againstGoals;
    if(gfga.forGoals>gfga.againstGoals)bucket.wins++;else if(gfga.forGoals===gfga.againstGoals)bucket.draws++;else bucket.losses++;

    const startingIds=new Set(startingLineupIds(match,out.roster).map(id=>String(id)));
    lineupIds(match,out.roster).forEach(id=>{
      const p=byId.get(String(id));if(!p)return;
      const isNonStartingGoalkeeper=isGoalkeeperPlayer(p)&&!startingIds.has(String(id));
      if(!isNonStartingGoalkeeper){
        p.appearances=toNumber(p.appearances)+1;
        p.competitions[comp].appearances=toNumber(p.competitions[comp].appearances)+1;
        p.competitions.totale.appearances=toNumber(p.competitions.totale.appearances)+1;
        if(p.history&&p.history[0])p.history[0].appearances=toNumber(p.history[0].appearances)+1;
      }
      // I portieri in panchina contano solo per i dati storici/all-time, non per la scheda rosa corrente.
      if(teamKey==="prima")addMap(appMap,id,1);
    });

    scorerEvents(match,out.roster).forEach(e=>{
      const p=byId.get(String(e.playerId));if(!p)return;
      p.goals=toNumber(p.goals)+e.goals;
      p.competitions[comp].goals=toNumber(p.competitions[comp].goals)+e.goals;
      p.competitions.totale.goals=toNumber(p.competitions.totale.goals)+e.goals;
      if(p.history&&p.history[0])p.history[0].goals=toNumber(p.history[0].goals)+e.goals;
      if(teamKey==="prima")addMap(goalMap,e.playerId,e.goals);
    });

    yellowCardEvents(match,out.roster).forEach(e=>{const p=byId.get(String(e.playerId));if(p)addCards(p,comp,e.count,0);});
    redCardEvents(match,out.roster).forEach(e=>{const p=byId.get(String(e.playerId));if(p)addCards(p,comp,0,e.count);});

    goalkeeperAgainstEvents(match,out.roster,gfga.againstGoals).forEach(e=>{
      const gk=byId.get(String(e.playerId));if(!gk||!gk.goalkeeperStats)return;
      const gs=gk.goalkeeperStats;
      [comp,"totale"].forEach(k=>{
        gs.byCompetition[k].appearances=toNumber(gs.byCompetition[k].appearances)+toNumber(e.appearances);
        gs.byCompetition[k].minutes=toNumber(gs.byCompetition[k].minutes)+toNumber(e.minutes);
        gs.byCompetition[k].goalsAgainst=toNumber(gs.byCompetition[k].goalsAgainst)+toNumber(e.goalsAgainst);
        if(toNumber(e.goalsAgainst)===0 && toNumber(e.appearances)>0)gs.byCompetition[k].cleanSheets=toNumber(gs.byCompetition[k].cleanSheets)+1;
      });
      gs.appearances=toNumber(gs.appearances)+toNumber(e.appearances);
      gs.minutes=toNumber(gs.minutes)+toNumber(e.minutes);
      gs.goalsAgainst=toNumber(gs.goalsAgainst)+toNumber(e.goalsAgainst);
      if(toNumber(e.goalsAgainst)===0 && toNumber(e.appearances)>0)gs.cleanSheets=toNumber(gs.cleanSheets)+1;
      gs.goalsAgainstAvg=gs.appearances?Number((gs.goalsAgainst/gs.appearances).toFixed(2)):0;
    });
  }

  (out.fixtures||[]).forEach(m=>processMatch(m,"campionato"));
  (out.u21Fixtures||[]).forEach(m=>processMatch(m,"u21"));

  function totals(obj){const a=obj.campionato,b=obj.coppa;const t={played:a.played+b.played,wins:a.wins+b.wins,draws:a.draws+b.draws,losses:a.losses+b.losses,goalsFor:a.goalsFor+b.goalsFor,goalsAgainst:a.goalsAgainst+b.goalsAgainst};t.goalDifference=t.goalsFor-t.goalsAgainst;return t;}
  out.currentSeasonStats={season,prima:{...teamStats.prima,totale:totals(teamStats.prima)},u21:{...teamStats.u21,totale:totals(teamStats.u21)}};
  goalMap.forEach((value,id)=>{const p=byId.get(String(id));if(p)playerIncrements.goals.push({name:p.name,value});});
  appMap.forEach((value,id)=>{const p=byId.get(String(id));if(p)playerIncrements.appearances.push({name:p.name,value});});
  out.historicalStats=historicalWithCurrentSeason(out.historicalStats,out.currentSeasonStats.prima.totale,season,playerIncrements);
  return out;
}

function fmt(d){
  if(!d) return "Da definire";
  const date = new Date(d);
  if(Number.isNaN(date.getTime())) return "Da definire";
  return new Intl.DateTimeFormat("it-IT",{day:"2-digit",month:"short",year:"numeric"}).format(date);
}

// ===== Selezione automatica basata sulla data odierna =====
function _d(x){ const t=Date.parse(x); return isNaN(t)? null : t; }
function nextFixture(list){
  const now=Date.now();
  const future=(list||[]).filter(f=>_d(f.date)!==null && _d(f.date)>=now-86400000)
    .sort((a,b)=>_d(a.date)-_d(b.date));
  if(future.length) return future[0];
  // riserva: primo con stato 'Da giocare', altrimenti il primo della lista
  return (list||[]).find(f=>normText(f.status)==='dagiocare') || (list||[])[0] || {};
}
function lastResult(list){
  const now=Date.now();
  const past=(list||[]).filter(f=>_d(f.date)!==null && _d(f.date)<now && (f.score||normText(f.status)==='terminata'))
    .sort((a,b)=>_d(b.date)-_d(a.date));
  if(past.length) return past[0];
  return [...(list||[])].reverse().find(f=>normText(f.status)==='terminata') || {};
}
function latestNews(list){
  const pinned=(list||[]).find(n=>n.pinned);
  if(pinned) return pinned;
  return [...(list||[])].sort((a,b)=>(_d(b.date)||0)-(_d(a.date)||0))[0] || {};
}
function closeMobileMenu(){
  const menu=$("#mobileMenu");
  const toggle=document.querySelector(".mobile-toggle");
  if(menu){
    menu.classList.remove("open");
    menu.setAttribute("aria-hidden","true");
  }
  if(toggle)toggle.setAttribute("aria-expanded","false");
  document.body.classList.remove("menu-open");
}
function openMobileMenu(){
  const menu=$("#mobileMenu");
  const toggle=document.querySelector(".mobile-toggle");
  if(menu){
    renderNav();
    menu.classList.add("open");
    menu.setAttribute("aria-hidden","false");
  }
  if(toggle)toggle.setAttribute("aria-expanded","true");
  document.body.classList.add("menu-open");
}
function scrollToPageTop(){
  const doScroll=()=>{
    try{window.scrollTo({top:0,left:0,behavior:"auto"});}
    catch(e){window.scrollTo(0,0);}
    if(document.documentElement)document.documentElement.scrollTop=0;
    if(document.body)document.body.scrollTop=0;
  };
  doScroll();
  requestAnimationFrame(doScroll);
  setTimeout(doScroll,60);
  setTimeout(doScroll,180);
}
function route(id){
  closeMobileMenu();
  const target=String(id||"home");
  const nextPath=appPathForRoute(target);
  if(nextPath && nextPath.startsWith("/") && history.pushState){
    const currentPath=normalizePathname(location.pathname);
    const normalizedNext=normalizePathname(nextPath);
    if(currentPath!==normalizedNext || location.hash){
      history.pushState(null,"",nextPath);
    }
    current=target;
    if(target === "news" || target.startsWith("article-")) scheduleImportedNewsArchiveLoad(0);
    render();
    scrollToPageTop();
    return;
  }
  if(location.hash!==`#${target}`){
    location.hash=target;
    return;
  }
  current=target;
  if(target === "news" || target.startsWith("article-")) scheduleImportedNewsArchiveLoad(0);
  render();
  scrollToPageTop();
}
function toggleMobile(){
  const menu=$("#mobileMenu");
  if(menu&&menu.classList.contains("open"))closeMobileMenu();
  else openMobileMenu();
}
window.addEventListener("hashchange",()=>{
  current=location.hash.replace("#","")||routeFromPath(location.pathname);
  if(current === "news" || String(current || "").startsWith("article-")) scheduleImportedNewsArchiveLoad(0);
  render();
  scrollToPageTop();
});
window.addEventListener("popstate",()=>{
  current=location.hash.replace("#","")||routeFromPath(location.pathname);
  if(current === "news" || String(current || "").startsWith("article-")) scheduleImportedNewsArchiveLoad(0);
  render();
  scrollToPageTop();
});
function setSEO(title,desc,img){
  const finalTitle=title+" | CUS Trento C5";
  const finalDesc=desc||`${title} — CUS Trento C5`;
  document.title=finalTitle;
  const metaDescription=$("#metaDescription"), ogTitle=$("#ogTitle"), ogDescription=$("#ogDescription"), ogImage=$("#ogImage"), canonical=$("#canonical");
  if(metaDescription)metaDescription.setAttribute("content",finalDesc);
  if(ogTitle)ogTitle.setAttribute("content",title);
  if(ogDescription)ogDescription.setAttribute("content",finalDesc);
  if(img&&ogImage)ogImage.setAttribute("content",img);
  if(canonical){
    const path=appPathForRoute(current);
    canonical.setAttribute("href",location.origin+(path&&path.startsWith("/")?path:normalizePathname(location.pathname)));
  }
}
function active(id){return current===id||current.startsWith(id+"-");}
function renderNav(){
  $("#navGroups").innerHTML=groups.map(g=>{
    if(g.items.length===1){const [id,label]=g.items[0];return `<div class="nav-group nav-single"><button class="nav-main ${active(id)?'active':''}" onclick="route('${id}')">${g.label}</button></div>`;}
    return `<div class="nav-group"><button class="nav-main ${g.items.some(i=>active(i[0]))?'active':''}">${g.label}</button><div class="dropdown">${g.items.map(([id,label])=>`<button class="${active(id)?'active':''}" onclick="route('${id}')">${label}</button>`).join("")}</div></div>`;
  }).join("");
  const quick=[
    ["fixtures","Calendario"],
    ["standings","Classifica"],
    ["squad","Rosa"],
    ["contacts","Contatti"]
  ];
  $("#mobileMenu").innerHTML=`
    <button class="mobile-backdrop" onclick="closeMobileMenu()" aria-label="Chiudi menu"></button>
    <aside class="mobile-sheet" role="dialog" aria-modal="true" aria-label="Menu principale">
      <div class="mobile-sheet-head">
        <div class="mobile-sheet-brand">${brandMark()}<div><b>CUS Trento C5</b><small>Menu rapido</small></div></div>
        <button class="mobile-close" onclick="closeMobileMenu()" aria-label="Chiudi menu">×</button>
      </div>
      <div class="mobile-quick">
        ${quick.map(([id,label])=>`<button class="${active(id)?'active':''}" onclick="route('${id}')">${label}</button>`).join("")}
      </div>
      <div class="mobile-nav-list">
        ${groups.map(g=>{
          if(g.items.length===1){const [id,label]=g.items[0];return `<button class="mobile-nav-item ${active(id)?'active':''}" onclick="route('${id}')"><span>${g.label}</span><b>›</b></button>`;}
          return `<details class="mobile-nav-group" ${g.items.some(i=>active(i[0]))?'open':''}><summary>${g.label}</summary><div>${g.items.map(([id,label])=>`<button class="mobile-nav-item ${active(id)?'active':''}" onclick="route('${id}')"><span>${label}</span><b>›</b></button>`).join("")}</div></details>`;
        }).join("")}
      </div>
    </aside>`;
}
